-- ----------------------------
-- Table structure for tb_core_function_menu
-- ----------------------------
DROP TABLE IF EXISTS `tb_core_function_menu`;
CREATE TABLE `tb_core_function_menu` (
  `id` bigint NOT NULL COMMENT '主键',
  `function_id` bigint NOT NULL COMMENT '功能ID',
  `menu_id` bigint NOT NULL COMMENT '菜单ID',
  `create_user` bigint NOT NULL DEFAULT '1' COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint NOT NULL DEFAULT '1' COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` bigint NOT NULL DEFAULT '0' COMMENT '删除时间',
  `create_org` bigint DEFAULT NULL COMMENT '创建部门',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `function_id_fk` (`function_id`) USING BTREE,
  KEY `menu_id_fk` (`menu_id`) USING BTREE,
  CONSTRAINT `function_id_fk` FOREIGN KEY (`function_id`) REFERENCES `tb_core_function` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `menu_id_fk` FOREIGN KEY (`menu_id`) REFERENCES `tb_core_top_menu` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='功能菜单顶级菜单关联表';

