DROP TABLE IF EXISTS `tb_core_role_data`;
CREATE TABLE `tb_core_role_data` (
  `id` bigint NOT NULL COMMENT '主键',
  `role_id` bigint NOT NULL COMMENT '角色ID',
  `data_id` bigint NOT NULL COMMENT '数据权限ID',
  `create_user` bigint NOT NULL DEFAULT '1' COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint NOT NULL DEFAULT '1' COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_org` bigint DEFAULT NULL COMMENT '创建部门',
  `delete_time` bigint NOT NULL DEFAULT '0' COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `core_dict_type` (`role_id`,`data_id`) USING BTREE,
  KEY `data_id_fk` (`data_id`) USING BTREE,
  CONSTRAINT `data_id_fk` FOREIGN KEY (`data_id`) REFERENCES `tb_core_data_scope` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `role_id_fk` FOREIGN KEY (`role_id`) REFERENCES `tb_core_role` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='角色数据权限关联表';

