  `delete_time` bigint NOT NULL DEFAULT '0' COMMENT '删除时间',
  `create_org` bigint DEFAULT NULL COMMENT '创建部门',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='文件表';

